import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        solve(in, out);
        out.close();
    }

    static void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        if (n > 11) {
            out.println("0");
            return;
        }
        ArrayList<Point> arr = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            arr.add(new Point(in.nextInt(), in.nextInt(), in.nextInt(), in.nextInt(), in.nextInt()));
        }
        Set<Integer> good = new LinkedHashSet<>();
        for (int i = 0; i < n; i++) {
            Point p = arr.get(i);
            boolean flag = true;
            for (int j = 0; j < n && flag; j++) {
                for (int k = 0; k < n && flag; k++) {
                    if (i != j && i != k && j != k) {
                        Point u = arr.get(j).minus(p);
                        Point v = arr.get(k).minus(p);
                        if (isAcute(u, v)) {
                            flag = false;
                        }
                    }
                }
            }
            if (flag) {
                good.add(i + 1);
            }
        }
        if (good.isEmpty()) {
            out.println("0");
        } else {
            out.println(good.size());
            for (int idx : good) {
                out.println(idx);
            }
        }
    }

    static boolean isAcute(Point u, Point v) {
        double mu = u.magnitude();
        double mv = v.magnitude();
        int dot = u.a*v.a + u.b*v.b + u.c*v.c + u.d*v.d + u.e*v.e;
        return Math.toDegrees(Math.acos(dot / (mu * mv))) < 90;
    }

    static class Point {
        int a, b, c, d, e;
        Point(int a, int b, int c, int d, int e) {
            this.a = a; this.b = b; this.c = c; this.d = d; this.e = e;
        }
        Point minus(Point o) {
            return new Point(a-o.a, b-o.b, c-o.c, d-o.d, e-o.e);
        }
        double magnitude() {
            return Math.sqrt(a*a + b*b + c*c + d*d + e*e);
        }
    }

    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;
        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException ex) {
                    throw new RuntimeException(ex);
                }
            }
            return tokenizer.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
